diffs.patch:
Index: index.html
===================================================================
--- index.html	
+++ index.html	
@@ -0,0 +1,538 @@
+<!DOCTYPE html>
+<html lang="en">
+<head>
+<meta charset="UTF-8">
+<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
+<title>STRIKE LINE — Browser FPS Playtest</title>
+<style>
+  * { margin:0; padding:0; box-sizing:border-box; }
+  html,body { width:100%; height:100%; overflow:hidden; background:#0b0e13; font-family:'Segoe UI',Arial,sans-serif; user-select:none; -webkit-user-select:none; }
+  #game { position:fixed; inset:0; }
+  canvas { display:block; }
+  /* ---------- HUD ---------- */
+  #hud { position:fixed; inset:0; pointer-events:none; z-index:10; display:none; }
+  #hud.on { display:block; }
+  #crosshair { position:absolute; left:50%; top:50%; transform:translate(-50%,-50%); width:40px; height:40px; }
+  #crosshair .dot { position:absolute; left:50%; top:50%; width:4px; height:4px; margin:-2px; background:#fff; border-radius:50%; box-shadow:0 0 3px #000; }
+  #crosshair .l { position:absolute; background:#fff; box-shadow:0 0 3px #000; transition:all .08s; }
+  #hitmarker { position:absolute; left:50%; top:50%; width:34px; height:34px; transform:translate(-50%,-50%) rotate(45deg); opacity:0; }
+  #hitmarker span { position:absolute; background:#ff3b3b; box-shadow:0 0 6px #ff3b3b; }
+  #hitmarker span:nth-child(1){left:0;top:50%;width:10px;height:2px;} #hitmarker span:nth-child(2){right:0;top:50%;width:10px;height:2px;}
+  #hitmarker span:nth-child(3){top:0;left:50%;height:10px;width:2px;} #hitmarker span:nth-child(4){bottom:0;left:50%;height:10px;width:2px;}
+  #hitmarker.show { animation:hit .25s ease-out; } #hitmarker.kill span { background:#ffcc00; box-shadow:0 0 8px #ffcc00; }
+  @keyframes hit { 0%{opacity:1; transform:translate(-50%,-50%) rotate(45deg) scale(1.4);} 100%{opacity:0; transform:translate(-50%,-50%) rotate(45deg) scale(.9);} }
+  #topbar { position:absolute; top:12px; left:0; right:0; display:flex; justify-content:center; gap:14px; align-items:center; }
+  .pill { background:rgba(8,12,18,.72); border:1px solid rgba(255,255,255,.14); color:#fff; padding:7px 16px; border-radius:20px; font-size:13px; letter-spacing:1.5px; font-weight:600; }
+  .pill b { color:#ffcc00; } .pill.danger b{color:#ff5252;}
+  #obj { position:absolute; top:56px; left:0; right:0; text-align:center; color:#ffd76a; font-size:13px; letter-spacing:1px; text-shadow:0 1px 4px #000; }
+  #killfeed { position:absolute; top:84px; right:16px; display:flex; flex-direction:column; gap:6px; align-items:flex-end; }
+  .kf { background:rgba(8,12,18,.75); border-right:3px solid #ffcc00; color:#fff; font-size:12px; padding:6px 10px; border-radius:6px; animation:kfin .25s ease-out; }
+  @keyframes kfin { from{transform:translateX(30px); opacity:0;} to{transform:none; opacity:1;} }
+  #bottom { position:absolute; left:0; right:0; bottom:0; display:flex; justify-content:space-between; align-items:flex-end; padding:18px 22px; }
+  #healthwrap { width:300px; }
+  #hpbar { height:14px; background:rgba(255,255,255,.12); border:1px solid rgba(255,255,255,.25); border-radius:8px; overflow:hidden; }
+  #hpfill { height:100%; width:100%; background:linear-gradient(90deg,#37e05c,#aef35a); transition:width .2s; }
+  #hpfill.low { background:linear-gradient(90deg,#ff2d2d,#ff7a5a); }
+  #hptext { color:#fff; font-weight:700; font-size:14px; margin-top:6px; text-shadow:0 1px 3px #000; letter-spacing:1px; }
+  #stance { color:#9fe8ff; font-size:11px; letter-spacing:2px; margin-top:3px; }
+  #ammo { text-align:right; color:#fff; text-shadow:0 2px 6px #000; }
+  #ammo .mag { font-size:44px; font-weight:800; line-height:1; } #ammo .mag small{font-size:18px; color:#aaa;}
+  #ammo .name { font-size:12px; letter-spacing:3px; color:#ffcc00; font-weight:700; }
+  #reloadtip { font-size:12px; color:#ff8a8a; margin-top:4px; height:16px; font-weight:700; letter-spacing:1px; animation:blink 1s infinite; }
+  @keyframes blink { 50%{opacity:.3;} }
+  #minimap { position:absolute; left:16px; top:84px; width:150px; height:150px; border-radius:50%; border:2px solid rgba(255,255,255,.35); background:rgba(5,10,8,.72); overflow:hidden; }
+  #dmgvin { position:fixed; inset:0; pointer-events:none; z-index:9; opacity:0; background:radial-gradient(ellipse at center, transparent 45%, rgba(255,0,0,.55) 100%); transition:opacity .15s; }
+  #healvin { position:fixed; inset:0; pointer-events:none; z-index:9; opacity:0; background:radial-gradient(ellipse at center, transparent 60%, rgba(0,255,120,.25) 100%); }
+  #dmgdir { position:absolute; left:50%; top:50%; width:120px; height:120px; margin:-60px; opacity:0; }
+  /* ---------- Screens ---------- */
+  .screen { position:fixed; inset:0; z-index:20; display:flex; align-items:center; justify-content:center; background:radial-gradient(ellipse at 50% 30%, rgba(40,60,90,.92), rgba(5,8,12,.96)), url(''); }
+  .card { max-width:620px; width:92%; background:rgba(10,15,22,.9); border:1px solid rgba(255,204,0,.35); border-radius:14px; padding:34px 38px; color:#fff; text-align:center; box-shadow:0 20px 80px rgba(0,0,0,.6); }
+  .card h1 { font-size:42px; letter-spacing:4px; font-weight:900; } .card h1 span{color:#ffcc00;}
+  .card h2 { font-size:30px; letter-spacing:3px; } .sub { color:#ffcc00; letter-spacing:4px; font-size:12px; font-weight:700; margin:6px 0 14px; }
+  .card p { color:#c7d0dc; font-size:14px; line-height:1.65; }
+  .keys { display:grid; grid-template-columns:1fr 1fr; gap:6px 18px; text-align:left; margin:18px auto 6px; max-width:440px; font-size:13px; color:#dbe4f0; }
+  .keys b { display:inline-block; min-width:86px; color:#0b0e13; background:#ffcc00; border-radius:5px; padding:2px 8px; font-size:12px; margin-right:8px; text-align:center; }
+  .btn { pointer-events:auto; cursor:pointer; display:inline-block; margin-top:20px; background:#ffcc00; color:#111; font-weight:800; letter-spacing:2px; font-size:16px; border:none; border-radius:8px; padding:14px 44px; transition:transform .1s; }
+  .btn:hover { transform:scale(1.04); background:#ffe04d; }
+  .btn.ghost { background:transparent; color:#fff; border:1px solid #555; margin-left:10px; }
+  #stats { display:flex; gap:18px; justify-content:center; margin:16px 0 4px; }
+  #stats div { background:rgba(255,255,255,.06); border-radius:8px; padding:10px 18px; } #stats b{font-size:22px; color:#ffcc00; display:block;}
+  #stats span{font-size:11px; letter-spacing:2px; color:#aaa;}
+  .hidden { display:none !important; }
+  #wavetrans { position:fixed; inset:0; z-index:15; display:flex; align-items:center; justify-content:center; pointer-events:none; opacity:0; transition:opacity .4s; }
+  #wavetrans h2 { color:#fff; font-size:52px; letter-spacing:8px; text-shadow:0 4px 30px #000; font-weight:900; } #wavetrans h2 span{color:#ffcc00;}
+  #wavetrans.show { opacity:1; }
+  #touchui { position:fixed; inset:0; z-index:11; pointer-events:none; display:none; }
+  #stick { position:absolute; left:26px; bottom:90px; width:120px; height:120px; border-radius:50%; background:rgba(255,255,255,.08); border:1px solid rgba(255,255,255,.3); pointer-events:auto; }
+  #nub { position:absolute; left:38px; top:38px; width:44px; height:44px; border-radius:50%; background:rgba(255,204,0,.8); }
+  #firebtn,#adsbtn,#jumpbtn { position:absolute; pointer-events:auto; border-radius:50%; border:1px solid rgba(255,255,255,.4); color:#fff; font-weight:800; display:flex; align-items:center; justify-content:center; }
+  #firebtn { right:30px; bottom:96px; width:92px; height:92px; background:rgba(255,60,60,.55); font-size:14px; }
+  #adsbtn { right:140px; bottom:70px; width:60px; height:60px; background:rgba(255,255,255,.15); font-size:11px; }
+  #jumpbtn { right:52px; bottom:200px; width:60px; height:60px; background:rgba(255,255,255,.15); font-size:11px; }
+  @media (max-width:700px){ #minimap{width:104px;height:104px;} #healthwrap{width:190px;} #ammo .mag{font-size:32px;} .card{padding:24px 20px;} .card h1{font-size:30px;} .keys{grid-template-columns:1fr;} }
+</style>
+<script type="importmap">{ "imports": { "three": "https://unpkg.com/three@0.160.0/build/three.module.js" } }</script>
+</head>
+<body>
+<div id="game"></div>
+<div id="dmgvin"></div><div id="healvin"></div>
+<div id="hud">
+  <div id="crosshair"><div class="dot"></div>
+    <div class="l" id="chT"></div><div class="l" id="chB"></div><div class="l" id="chL"></div><div class="l" id="chR"></div>
+  </div>
+  <div id="hitmarker"><span></span><span></span><span></span><span></span></div>
+  <svg id="dmgdir" viewBox="0 0 120 120"><path id="dmgarrow" d="M60 6 L74 34 L60 27 L46 34 Z" fill="rgba(255,40,40,.9)"/></svg>
+  <div id="topbar">
+    <div class="pill" id="wavepill">WAVE <b>1 / 3</b></div>
+    <div class="pill" id="enemypill">HOSTILES <b>4</b></div>
+    <div class="pill" id="killpill">KILLS <b>0</b></div>
+    <div class="pill" id="timepill">TIME <b>0:00</b></div>
+  </div>
+  <div id="obj">◉ ELIMINATE ALL HOSTILES — clear 3 waves to win</div>
+  <canvas id="minimap" width="150" height="150"></canvas>
+  <div id="killfeed"></div>
+  <div id="bottom">
+    <div id="healthwrap"><div id="hpbar"><div id="hpfill"></div></div><div id="hptext">100 HP</div><div id="stance">SHIFT SPRINT · SPACE JUMP · R RELOAD · RMB AIM</div></div>
+    <div id="ammo"><div class="name">AR-7 STRIKER · AUTO</div><div class="mag"><span id="mag">30</span><small> / <span id="reserve">90</span></small></div><div id="reloadtip"></div></div>
+  </div>
+</div>
+<div id="wavetrans"><h2 id="wavetransText">WAVE <span>1</span></h2></div>
+<div id="touchui"><div id="stick"><div id="nub"></div></div><div id="firebtn">FIRE</div><div id="adsbtn">ADS</div><div id="jumpbtn">JUMP</div></div>
+
+<div class="screen" id="menu">
+  <div class="card">
+    <h1>STRIKE <span>LINE</span></h1>
+    <div class="sub">★ BROWSER FPS PLAYTEST ★</div>
+    <p>A Call-of-Duty-style first-person shooter that runs entirely in your browser. Fight through <b style="color:#fff">3 waves</b> of hostiles across the compound. Health regenerates out of combat — keep moving, aim for the head, watch your ammo.</p>
+    <div class="keys">
+      <div><b>W A S D</b> Move</div><div><b>MOUSE</b> Look / aim</div>
+      <div><b>LMB</b> Fire</div><div><b>RMB</b> Aim down sights</div>
+      <div><b>R</b> Reload</div><div><b>SHIFT / SPACE</b> Sprint / Jump</div>
+    </div>
+    <button class="btn" id="playBtn">▶ DEPLOY</button>
+    <p style="margin-top:12px;font-size:12px;color:#8b96a5">Click locks your mouse · ESC pauses · sound on recommended 🔊</p>
+  </div>
+</div>
+
+<div class="screen hidden" id="pause">
+  <div class="card"><h2>⏸ PAUSED</h2><div class="sub">CATCH YOUR BREATH, SOLDIER</div>
+    <p>Pointer unlocked. Click resume to re-lock and keep fighting.</p>
+    <div style="font-size:13px;color:#c7d0dc;margin-top:10px">Sensitivity: <input id="sens" type="range" min="0.3" max="3" step="0.1" value="1" style="width:180px;vertical-align:middle;pointer-events:auto"> <span id="sensv">1.0</span></div>
+    <button class="btn" id="resumeBtn">RESUME</button><button class="btn ghost" id="quitBtn">RESTART</button>
+  </div>
+</div>
+
+<div class="screen hidden" id="end">
+  <div class="card"><h2 id="endTitle">🏆 MISSION COMPLETE</h2><div class="sub" id="endSub">ALL WAVES CLEARED</div>
+    <p id="endText"></p><div id="stats"></div>
+    <button class="btn" id="againBtn">↻ PLAY AGAIN</button>
+  </div>
+</div>
+
+<script type="module">
+import * as THREE from 'three';
+
+/* ================= AUDIO (synthesized, no files) ================= */
+let AC=null; function ac(){ if(!AC){ AC=new (window.AudioContext||window.webkitAudioContext)(); } if(AC.state==='suspended')AC.resume(); return AC; }
+function noiseBuf(dur){ const c=ac(),b=c.createBuffer(1,c.sampleRate*dur,c.sampleRate),d=b.getChannelData(0); for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1; return b; }
+function shot(suppressed=false){ try{ const c=ac(),t=c.currentTime;
+  const n=c.createBufferSource(); n.buffer=noiseBuf(0.18); const f=c.createBiquadFilter(); f.type='lowpass'; f.frequency.setValueAtTime(suppressed?900:3200,t); f.frequency.exponentialRampToValueAtTime(220,t+0.12);
+  const g=c.createGain(); g.gain.setValueAtTime(suppressed?0.25:0.55,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.16);
+  n.connect(f).connect(g).connect(c.destination); n.start(t); n.stop(t+0.2);
+  const o=c.createOscillator(); o.type='square'; o.frequency.setValueAtTime(suppressed?120:160,t); o.frequency.exponentialRampToValueAtTime(40,t+0.1);
+  const g2=c.createGain(); g2.gain.setValueAtTime(0.25,t); g2.gain.exponentialRampToValueAtTime(0.001,t+0.1); o.connect(g2).connect(c.destination); o.start(t); o.stop(t+0.12);
+}catch(e){} }
+function eshot(){ try{ const c=ac(),t=c.currentTime; const n=c.createBufferSource(); n.buffer=noiseBuf(0.15); const f=c.createBiquadFilter(); f.type='lowpass'; f.frequency.value=1400;
+  const g=c.createGain(); g.gain.setValueAtTime(0.22,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.14); n.connect(f).connect(g).connect(c.destination); n.start(t); n.stop(t+0.16);}catch(e){} }
+function snd(freq,dur,type='sine',vol=0.2,slide=null){ try{ const c=ac(),t=c.currentTime,o=c.createOscillator(),g=c.createGain(); o.type=type; o.frequency.setValueAtTime(freq,t); if(slide)o.frequency.exponentialRampToValueAtTime(slide,t+dur);
+  g.gain.setValueAtTime(vol,t); g.gain.exponentialRampToValueAtTime(0.001,t+dur); o.connect(g).connect(c.destination); o.start(t); o.stop(t+dur+0.02);}catch(e){} }
+const sHit=()=>snd(1200,0.08,'square',0.12,700), sKill=()=>{snd(700,0.1,'square',0.15,1400); setTimeout(()=>snd(1050,0.14,'square',0.15,1600),80);},
+sReload=()=>{snd(300,0.08,'square',0.12); setTimeout(()=>snd(450,0.08,'square',0.12),180); setTimeout(()=>snd(600,0.1,'square',0.14),420);},
+sHurt=()=>snd(140,0.25,'sawtooth',0.25,60), sEmpty=()=>snd(1800,0.05,'square',0.08), sPickup=()=>snd(520,0.12,'sine',0.18,880), sWave=()=>{snd(392,0.2,'sawtooth',0.12); setTimeout(()=>snd(523,0.25,'sawtooth',0.12),180);};
+
+/* ================= RENDERER / SCENE ================= */
+const container=document.getElementById('game');
+const renderer=new THREE.WebGLRenderer({antialias:true});
+renderer.setSize(innerWidth,innerHeight); renderer.setPixelRatio(Math.min(devicePixelRatio,2));
+renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap;
+container.appendChild(renderer.domElement);
+const scene=new THREE.Scene();
+scene.background=new THREE.Color(0x87a5c4); scene.fog=new THREE.Fog(0x87a5c4,30,140);
+const camera=new THREE.PerspectiveCamera(75,innerWidth/innerHeight,0.05,300);
+const hemi=new THREE.HemisphereLight(0xcfe8ff,0x5a6448,1.1); scene.add(hemi);
+const sun=new THREE.DirectionalLight(0xfff2d8,1.25); sun.position.set(30,45,18); sun.castShadow=true;
+sun.shadow.mapSize.set(2048,2048); sun.shadow.camera.left=-60; sun.shadow.camera.right=60; sun.shadow.camera.top=60; sun.shadow.camera.bottom=-60; scene.add(sun);
+
+/* sky sun sprite + clouds */
+{ const cv=document.createElement('canvas'); cv.width=cv.height=128; const g=cv.getContext('2d');
+  const gr=g.createRadialGradient(64,64,4,64,64,64); gr.addColorStop(0,'rgba(255,250,220,1)'); gr.addColorStop(0.3,'rgba(255,240,190,.9)'); gr.addColorStop(1,'rgba(255,240,190,0)');
+  g.fillStyle=gr; g.fillRect(0,0,128,128); const tx=new THREE.CanvasTexture(cv);
+  const sm=new THREE.SpriteMaterial({map:tx,transparent:true,depthWrite:false,fog:false}); const sp=new THREE.Sprite(sm); sp.scale.set(26,26,1); sp.position.set(90,70,-120); scene.add(sp); }
+
+/* ================= MAP ================= */
+const ARENA=56; // half-size
+const colliders=[]; // {x,z,hx,hz}
+function addCollider(x,z,hx,hz){ colliders.push({x,z,hx,hz}); }
+const groundTex=(()=>{ const c=document.createElement('canvas'); c.width=c.height=256; const g=c.getContext('2d');
+  g.fillStyle='#6f7d4f'; g.fillRect(0,0,256,256);
+  for(let i=0;i<2600;i++){ g.fillStyle=`rgba(${40+Math.random()*60|0},${60+Math.random()*50|0},${25+Math.random()*30|0},.5)`; g.fillRect(Math.random()*256,Math.random()*256,2,2); }
+  g.strokeStyle='rgba(0,0,0,.15)'; for(let i=0;i<=4;i++){ g.beginPath(); g.moveTo(i*64,0); g.lineTo(i*64,256); g.stroke(); g.beginPath(); g.moveTo(0,i*64); g.lineTo(256,i*64); g.stroke(); }
+  const t=new THREE.CanvasTexture(c); t.wrapS=t.wrapT=THREE.RepeatWrapping; t.repeat.set(18,18); return t; })();
+const ground=new THREE.Mesh(new THREE.PlaneGeometry(ARENA*2+40,ARENA*2+40),new THREE.MeshLambertMaterial({map:groundTex}));
+ground.rotation.x=-Math.PI/2; ground.receiveShadow=true; scene.add(ground);
+// perimeter walls
+const wallMat=new THREE.MeshLambertMaterial({color:0xa8adb4});
+const wallMat2=new THREE.MeshLambertMaterial({color:0x6b7076});
+function wall(x,z,w,d,h=4){ const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),wallMat); m.position.set(x,h/2,z); m.castShadow=m.receiveShadow=true; scene.add(m); addCollider(x,z,w/2,d/2); return m; }
+wall(0,-ARENA-1,ARENA*2+8,2,5); wall(0,ARENA+1,ARENA*2+8,2,5); wall(-ARENA-1,0,2,ARENA*2+8,5); wall(ARENA+1,0,2,ARENA*2+8,5);
+// sandbag stripes on walls
+for(let i=-48;i<=48;i+=8){ const s=new THREE.Mesh(new THREE.BoxGeometry(3,1,0.6),new THREE.MeshLambertMaterial({color:0xa08c5b})); s.position.set(i,4.4,-ARENA-0.6); scene.add(s); const s2=s.clone(); s2.position.z=ARENA+0.6; scene.add(s2); }
+// crates / cover
+const crateMats=[0x9c7a4d,0x7a8b5a,0x5f6e5e].map(c=>new THREE.MeshLambertMaterial({color:c}));
+function crate(x,z,s=2,h=null){ h=h||s; const m=new THREE.Mesh(new THREE.BoxGeometry(s,h,s),crateMats[(Math.random()*3)|0]); m.position.set(x,h/2,z); m.rotation.y=(Math.random()*0.3-0.15); m.castShadow=m.receiveShadow=true; scene.add(m); addCollider(x,z,s/2,s/2);
+  const e=new THREE.Mesh(new THREE.BoxGeometry(s+0.06,h*0.2,s+0.06),new THREE.MeshLambertMaterial({color:0x3d3423})); e.position.set(x,h*0.55,z); e.rotation.y=m.rotation.y; scene.add(e); return m; }
+crate(-10,-8,3); crate(-7,-8,2); crate(-8.2,-8,2,4.2); crate(10,-12,2.5); crate(12.5,-11,2); crate(0,-20,3); crate(-3,-20,2);
+crate(12,6,3); crate(9,8,2); crate(-14,10,2.5); crate(-16,7,2); crate(4,16,3); crate(1,17,2); crate(20,-2,2.5); crate(-22,-4,2.5);
+crate(6,-4,2); crate(-4,2,2); crate(-2,-2,1.6); crate(18,16,2.5); crate(-20,-18,2.5); crate(22,22,2); crate(-24,22,2);
+// watchtower
+function tower(x,z){ const g=new THREE.Group(); const legG=new THREE.BoxGeometry(0.5,7,0.5); const lm=new THREE.MeshLambertMaterial({color:0x5a4630});
+  [[-1.6,-1.6],[1.6,-1.6],[-1.6,1.6],[1.6,1.6]].forEach(([a,b])=>{ const l=new THREE.Mesh(legG,lm); l.position.set(a,3.5,b); l.castShadow=true; g.add(l); });
+  const floor=new THREE.Mesh(new THREE.BoxGeometry(4.6,0.4,4.6),new THREE.MeshLambertMaterial({color:0x7a5f3d})); floor.position.y=7; floor.castShadow=true; g.add(floor);
+  const roof=new THREE.Mesh(new THREE.ConeGeometry(3.6,1.6,4),new THREE.MeshLambertMaterial({color:0x4d5a43})); roof.position.y=9.4; roof.rotation.y=Math.PI/4; roof.castShadow=true; g.add(roof);
+  g.position.set(x,0,z); scene.add(g); addCollider(x,z,2,2); }
+tower(-26,-24); tower(26,24);
+// tents
+function tent(x,z,ry=0){ const g=new THREE.Group(); const m=new THREE.Mesh(new THREE.CylinderGeometry(0.1,3.4,2.8,6,1),new THREE.MeshLambertMaterial({color:0x6d7154})); m.position.y=1.4; m.castShadow=m.receiveShadow=true; g.add(m); g.position.set(x,0,z); g.rotation.y=ry; scene.add(g); addCollider(x,z,2.4,2.4); }
