const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({ args: ['--use-gl=swiftshader','--enable-unsafe-swiftshader','--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text().slice(0,300)); });
  page.on('pageerror', e => errors.push('PAGEERROR: '+String(e).slice(0,300)));
  await page.goto('file:///Users/runner/work/PlayGround/PlayGround/index.html', { waitUntil: 'networkidle', timeout: 45000 });
  await page.waitForTimeout(5000);
  await page.screenshot({ path: 'screenshots/menu.png' });
  console.log('MENU_ERRORS:', JSON.stringify(errors.slice(0,10)));
  // Start game via clicking deploy (pointer lock may fail headless; still check state)
  await page.click('#playBtn').catch(e => console.log('click fail', e.message));
  await page.waitForTimeout(6000);
  await page.screenshot({ path: 'screenshots/gameplay.png' });
  const state = await page.evaluate(() => {
    const g = window.__game;
    return g ? { wave: g.wave, enemies: g.enemies.length, hp: g.player.hp, mag: g.gun.mag } : null;
  });
  console.log('STATE:', JSON.stringify(state));
  console.log('ERRORS2:', JSON.stringify(errors.slice(0,10)));
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

