const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({ args: ['--use-gl=swiftshader','--enable-unsafe-swiftshader','--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text().slice(0,200)); });
  page.on('pageerror', e => errors.push('PAGEERROR: '+String(e).slice(0,200)));
  await page.goto('file:///Users/runner/work/PlayGround/PlayGround/index.html', { waitUntil: 'networkidle', timeout: 45000 });
  await page.waitForTimeout(4000);
  await page.click('#playBtn').catch(e => console.log('click fail', e.message));
  await page.waitForTimeout(4000);
  await page.screenshot({ path: 'screenshots/gameplay.png' });
  // combat test: aim & fire at nearest enemy repeatedly
  let out = [];
  for (let i = 0; i < 40; i++) {
    const r = await page.evaluate(() => window.__game.debugKillNearest());
    out.push(r);
    await page.waitForTimeout(130);
    const k = await page.evaluate(() => window.__game.player.kills);
    if (k > 0) break;
  }
  const state = await page.evaluate(() => ({ wave: window.__game.wave, kills: window.__game.player.kills, shots: window.__game.player.shots, hits: window.__game.player.hits, mag: window.__game.gun.mag, hp: Math.round(window.__game.player.hp), alive: window.__game.enemies.filter(e=>!e.dead).length }));
  console.log('SHOOT_SAMPLE:', JSON.stringify(out.slice(0,6)));
  console.log('STATE:', JSON.stringify(state));
  await page.screenshot({ path: 'screenshots/combat.png' });
  console.log('ERRORS:', JSON.stringify(errors.slice(0,8)));
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

