   #hitmarker.show { animation:hit .25s ease-out; } #hitmarker.kill span { background:#ffcc00; box-shadow:0 0 8px #ffcc00; }
   @keyframes hit { 0%{opacity:1; transform:translate(-50%,-50%) rotate(45deg) scale(1.4);} 100%{opacity:0; transform:translate(-50%,-50%) rotate(45deg) scale(.9);} }
   #topbar { position:absolute; top:12px; left:0; right:0; display:flex; justify-content:center; gap:14px; align-items:center; }
   .pill { background:rgba(8,12,18,.72); border:1px solid rgba(255,255,255,.14); color:#fff; padding:7px 16px; border-radius:20px; font-size:13px; letter-spacing:1.5px; font-weight:600; }
