$('againBtn').onclick=()=>{ $('end').classList.add('hidden'); resetGame(); renderer.domElement.requestPointerLock(); };
function startGame(){ $('menu').classList.add('hidden'); $('hud').classList.add('on'); running=true; gameOver=false; resetGame(); renderer.domElement.requestPointerLock(); }
function resetGame(){ player.hp=100; player.alive=true; player.kills=0; player.shots=0; player.hits=0; player.pos.set(0,1.7,24); player.vel.set(0,0,0); player.yaw=0; player.pitch=0;
  gun.mag=gun.magSize; gun.reserve=120; gun.reloading=false;
  for(const e of enemies)scene.remove(e.g); enemies.length=0;
  for(const p of pickups){scene.remove(p.m);scene.remove(p.ring);} pickups.length=0;
  document.getElementById('killfeed').innerHTML='';
  wave=0; player.startTime=performance.now(); nextWave(); updatePills(); updateAmmo(); updateHP(); }
function nextWave(){ wave++; if(wave>WAVES.length){ win(); return; } betweenWaves=false; spawnWave(WAVES[wave-1]); }
function win(){ gameOver=true; running=true; document.exitPointerLock&&document.exitPointerLock(); showEnd(true); }
function lose(){ gameOver=true; player.alive=false; document.exitPointerLock&&document.exitPointerLock(); showEnd(false); }
function showEnd(won){ const t=(performance.now()-player.startTime)/1000; const acc=player.shots?Math.round(player.hits/player.shots*100):0;
  $('endTitle').textContent=won?'🏆 MISSION COMPLETE':'☠ KIA — MISSION FAILED';
  $('endSub').textContent=won?'ALL 3 WAVES CLEARED':`FELL IN WAVE ${wave} OF 3`;
  $('endText').textContent=won?`Outstanding work, soldier. The compound is clear. Time: ${fmtT(t)} · Accuracy: ${acc}%.`:`You went down with ${enemiesLeft()} hostiles still standing. Hit DEPLOY to retry — keep moving and use cover.`;
  $('stats').innerHTML=`<div><b>${player.kills}</b><span>KILLS</span></div><div><b>${acc}%</b><span>ACCURACY</span></div><div><b>${fmtT(t)}</b><span>TIME</span></div>`;
  $('end').classList.remove('hidden'); snd(won?523:200,won?0.5:0.8,'sawtooth',0.15); }
function enemiesLeft(){ return enemies.filter(e=>!e.dead).length; }
function updatePills(){ $('wavepill').innerHTML=`WAVE <b>${Math.min(wave,3)} / 3</b>`; const l=enemiesLeft(); $('enemypill').innerHTML=`HOSTILES <b>${l}</b>`; $('enemypill').classList.toggle('danger',l>0); $('killpill').innerHTML=`KILLS <b>${player.kills}</b>`; }
function updateAmmo(){ $('mag').textContent=gun.mag; $('reserve').textContent=gun.reserve; $('reloadtip').textContent=(gun.mag<=6&&!gun.reloading)?'⚠ PRESS R TO RELOAD':(gun.reloading?'RELOADING…':''); }
function updateHP(){ $('hpfill').style.width=player.hp+'%'; $('hpfill').classList.toggle('low',player.hp<=35); $('hptext').textContent=`${Math.max(0,Math.ceil(player.hp))} HP`; }
function fmtT(s){ s=Math.floor(s); return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`; }
function hitmarker(kill=false){ const h=$('hitmarker'); h.classList.remove('show','kill'); void h.offsetWidth; if(kill)h.classList.add('kill'); h.classList.add('show'); }
function damagePlayer(amt,from){ if(!player.alive||gameOver)return; player.hp-=amt; player.lastDamage=perfNow(); sHurt();
  const v=$('dmgvin'); v.style.opacity=Math.min(0.9,0.3+amt/20); setTimeout(()=>v.style.opacity=Math.max(0,(100-player.hp)/160),120);
  // directional arrow
  const dx=from.x-player.pos.x,dz=from.z-player.pos.z; const worldA=Math.atan2(dx,-dz); let rel=worldA-(-player.yaw+Math.PI); const arrow=$('dmgdir');
  arrow.style.transform=`rotate(${(-rel*180/Math.PI+180)}deg)`; arrow.style.opacity=1; setTimeout(()=>arrow.style.opacity=0,600);
  // camera shake
  player.pitch+=(Math.random()-0.5)*0.03; player.yaw+=(Math.random()-0.5)*0.03;
  updateHP(); if(player.hp<=0){ player.hp=0; updateHP(); lose(); } }

/* ================= SHOOTING ================= */
const ray=new THREE.Raycaster(); ray.camera=camera; const fwd=new THREE.Vector3();
function startReload(){ if(gun.reloading||gun.mag===gun.magSize||gun.reserve<=0||!player.alive)return; gun.reloading=true; sReload(); updateAmmo();
  setTimeout(()=>{ const need=gun.magSize-gun.mag, take=Math.min(need,gun.reserve); gun.mag+=take; gun.reserve-=take; gun.reloading=false; updateAmmo(); },1400); }
function shoot(now){ if(gun.reloading||now-gun.lastShot<gun.rof)return;
  if(gun.mag<=0){ sEmpty(); gun.lastShot=now; if(gun.reserve>0)startReload(); return; }
  gun.mag--; gun.lastShot=now; player.shots++; shot(gun.adsTarget>0.5);
  gun.kick=Math.min(gun.kick+0.035,0.12); gun.spread=0.012+gun.kick*0.15+(moveMag>3?0.02:0);
  muzzle.intensity=26; flash.material.opacity=1; flash.material.rotation=Math.random()*Math.PI;
  camera.getWorldDirection(fwd);
  const spread=gun.spread*(gun.adsTarget>0.5?0.35:1);
  fwd.x+=(Math.random()-0.5)*spread*2; fwd.y+=(Math.random()-0.5)*spread*2; fwd.z+=(Math.random()-0.5)*spread*2; fwd.normalize();
  ray.set(camera.position,fwd); ray.far=120;
  const targets=enemies.filter(e=>!e.dead).map(e=>e.g);
  const hits=ray.intersectObjects(targets,true);
  const origin=camera.position.clone(); const dir=fwd.clone();
  let end=origin.clone().add(dir.clone().multiplyScalar(90));
  // wall distance cap
  const wallHit=ray.intersectObjects(scene.children.filter(o=>o.geometry&&o.geometry.type==='BoxGeometry'&&o!==ground),false)[0];
  if(hits.length){ const h=hits[0]; end=h.point.clone();
    let root=null,p=h.object; while(p){ if(p.userData&&p.userData.eid!==undefined){root=p;break;} p=p.parent; }
    // find enemy by traversing up to group
    let e=null; for(const en of enemies){ if(!en.dead&&(en.g===h.object||en.g.children.includes(h.object)||isChild(en.g,h.object))){e=en;break;} }
    if(e){ player.hits++; const headshot=h.object===e.head; const dmg=(headshot?55+Math.random()*20:gun.damage[0]+Math.random()*(gun.damage[1]-gun.damage[0]));
      e.hp-=dmg; enemyBar(e); spawnImpact(h.point,0xc41e1e,headshot?12:7);
      if(e.hp<=0)killEnemy(e); else { sHit(); hitmarker(false); floater(headshot?'HEADSHOT '+Math.round(dmg):Math.round(dmg),h.point.clone(),headshot?'#ff5252':'#fff'); e.state='chase'; }
    } else spawnImpact(h.point,0xffd27a,6);
  } else if(wallHit&&wallHit.distance<90){ end=wallHit.point.clone(); spawnImpact(end,0xcfc39a,5); }
  spawnTracer(origin.clone().add(dir.clone().multiplyScalar(1.2)).add(new THREE.Vector3(0.15,-0.15,0)),dir);
  // shell + gun snap handled in animate via kick
  updateAmmo(); if(gun.mag===0&&gun.reserve>0)setTimeout(()=>startReload(),250);
}
function isChild(root,obj){ let p=obj; while(p){ if(p===root)return true; p=p.parent; } return false; }

/* ================= COLLISION / MOVE ================= */
function collide(p,r=0.6){ for(const c of colliders){ const dx=p.x-c.x,dz=p.z-c.z; const px=c.hx+r-Math.abs(dx),pz=c.hz+r-Math.abs(dz);
    if(px>0&&pz>0){ if(px<pz)p.x=c.x+Math.sign(dx||1)*(c.hx+r); else p.z=c.z+Math.sign(dz||1)*(c.hz+r); } }
  p.x=Math.max(-ARENA,Math.min(ARENA,p.x)); p.z=Math.max(-ARENA,Math.min(ARENA,p.z)); }
let moveMag=0;
function updatePlayer(dt,now){ const sprint=(keys['ShiftLeft']||keys['ShiftRight'])&&!gun.adsTarget; const speed=(sprint?9:5.6)*(gun.adsTarget?0.55:1);
  let ix=0,iz=0; if(keys['KeyW']||keys['ArrowUp'])iz-=1; if(keys['KeyS']||keys['ArrowDown'])iz+=1; if(keys['KeyA']||keys['ArrowLeft'])ix-=1; if(keys['KeyD']||keys['ArrowRight'])ix+=1;
  ix+=touch.mx; iz+=touch.mz; const l=Math.hypot(ix,iz); if(l>1){ix/=l;iz/=l;}
  const sin=Math.sin(player.yaw),cos=Math.cos(player.yaw);
  const wx=(ix*cos-iz*sin)*speed, wz=(ix*sin+iz*cos)*speed*-1;
  // careful: compute forward properly: forward = (-sin(yaw), -cos(yaw)) for yaw convention
  const fx=-Math.sin(player.yaw),fz=-Math.cos(player.yaw); const rx=Math.cos(player.yaw),rz=-Math.sin(player.yaw);
  let vx=(fx*-iz+rx*ix)*speed, vz=(fz*-iz+rz*ix)*speed;
  player.vel.x+=(vx-player.vel.x)*Math.min(1,dt*10); player.vel.z+=(vz-player.vel.z)*Math.min(1,dt*10);
  player.vel.y-=16*dt; if(keys['Space']&&player.onGround){player.vel.y=5.4;player.onGround=false;}
  player.pos.x+=player.vel.x*dt; player.pos.z+=player.vel.z*dt; player.pos.y+=player.vel.y*dt;
  if(player.pos.y<=1.7){player.pos.y=1.7;player.vel.y=0;player.onGround=true;}
  collide(player.pos);
  moveMag=Math.hypot(player.vel.x,player.vel.z);
  // headbob
  const bobT=now*0.001*(sprint?13:9); const bobA=Math.min(moveMag/6,1)*(player.onGround?1:0);
  const bobY=Math.sin(bobT*2)*0.035*bobA, bobX=Math.cos(bobT)*0.025*bobA;
  camera.position.set(player.pos.x+bobX*Math.cos(player.yaw),player.pos.y+bobY,player.pos.z+bobX*Math.sin(player.yaw));
  camera.rotation.order='YXZ'; camera.rotation.y=player.yaw+gun.kick*0.4; camera.rotation.x=player.pitch+gun.kick*0.7; camera.rotation.z=bobX*0.6;
  gun.kick=Math.max(0,gun.kick-dt*0.35);
  // ADS
  gun.ads+=((gun.adsTarget?1:0)-gun.ads)*Math.min(1,dt*12);
  const a=gun.ads;   vmGroup.position.set(0.24*(1-a)+0*(a),-0.26*(1-a)-0.21*(a)+bobY*0.4,-0.35*(1-a)-0.25*a);
  camera.fov=75-12*a; camera.updateProjectionMatrix();
  muzzle.intensity=Math.max(0,muzzle.intensity-dt*320); flash.material.opacity=Math.max(0,flash.material.opacity-dt*14);
  // crosshair spread
  const sp=10+gun.kick*260+moveMag*2.2-8*a;
  $('chT').style.cssText=`left:19px;top:${20-sp}px;width:2px;height:8px;`; $('chB').style.cssText=`left:19px;top:${20+sp-8}px;width:2px;height:8px;`;
  $('chL').style.cssText=`top:19px;left:${20-sp}px;height:2px;width:8px;`; $('chR').style.cssText=`top:19px;left:${20+sp-8}px;height:2px;width:8px;`;
  $('crosshair').style.opacity=gun.ads>0.6?0.15:1;
  // health regen (CoD style)
  if(player.alive&&now-player.lastDamage>4000&&player.hp<player.maxHp){ player.hp=Math.min(player.maxHp,player.hp+dt*22); updateHP(); $('healvin').style.opacity=0.6; } else $('healvin').style.opacity=0;
  // pickups
  for(let i=pickups.length-1;i>=0;i--){ const p=pickups[i]; p.m.rotation.y+=dt*2; p.m.position.y=0.7+Math.sin(now*0.004+i)*0.12; p.life-=dt;
    if(p.life<=0){scene.remove(p.m);scene.remove(p.ring);pickups.splice(i,1);continue;}
    const d=Math.hypot(p.m.position.x-player.pos.x,p.m.position.z-player.pos.z);
    if(d<1.4){ if(p.kind==='hp'){player.hp=Math.min(player.maxHp,player.hp+35);updateHP();feed('✚ +35 HP');} else {gun.reserve=Math.min(180,gun.reserve+30);updateAmmo();feed('▤ +30 AMMO');} sPickup(); scene.remove(p.m);scene.remove(p.ring);pickups.splice(i,1); } }
  if(mouse.down)shoot(now/1000);
  $('timepill').innerHTML=`TIME <b>${fmtT((performance.now()-player.startTime)/1000)}</b>`;
}

/* ================= ENEMY AI ================= */
const tmpV=new THREE.Vector3();
function updateEnemies(dt,now){ let alive=0;
  for(const e of enemies){ if(e.dead){ e.deathT+=dt; e.g.rotation.x=Math.min(Math.PI/2,e.deathT*4); e.g.position.y=Math.max(-0.4,e.g.position.y-dt*0.4); e.bar.visible=false;
      if(e.deathT>3){scene.remove(e.g);} continue; }
    alive++; tmpV.set(player.pos.x-e.g.position.x,0,player.pos.z-e.g.position.z); const dist=tmpV.length(); tmpV.normalize();
    e.strafe+=dt*0.8*e.strafeDir; if(Math.random()<dt*0.3)e.strafeDir*=-1;
    // movement: approach until ~10m, then strafe
    let mx=0,mz=0;
    if(dist>11){ mx=tmpV.x*e.speed; mz=tmpV.z*e.speed; }
    else if(dist<6){ mx=-tmpV.x*e.speed*0.8; mz=-tmpV.z*e.speed*0.8; }
    else { mx=-tmpV.z*e.strafeDir*e.speed*0.6+tmpV.x*0.3; mz=tmpV.x*e.strafeDir*e.speed*0.6+tmpV.z*0.3; }
    e.g.position.x+=mx*dt; e.g.position.z+=mz*dt;
    // collide with cover (cheap)
    const p=e.g.position; for(const c of colliders){ const dx=p.x-c.x,dz=p.z-c.z; const px=c.hx+0.5-Math.abs(dx),pz=c.hz+0.5-Math.abs(dz);
      if(px>0&&pz>0){ if(px<pz)p.x=c.x+Math.sign(dx||1)*(c.hx+0.5); else p.z=c.z+Math.sign(dz||1)*(c.hz+0.5); } }
    p.x=Math.max(-ARENA,Math.min(ARENA,p.x)); p.z=Math.max(-ARENA,Math.min(ARENA,p.z));
    e.g.rotation.y=Math.atan2(tmpV.x,-tmpV.z)+Math.PI; // face player (model faces -z? adjust)
    e.g.rotation.y=Math.atan2(player.pos.x-p.x,player.pos.z-p.z);
    // walk bob
    e.g.position.y=Math.abs(Math.sin(now*0.008+e.strafe))*0.08*(dist>6?1:0.4);
    // shooting
    e.shootCd-=dt;
    if(e.shootCd<=0&&dist<42){ // line of sight check (cheap: ignore, cover reduces hit chance)
      e.shootCd=1.1+Math.random()*1.6-wave*0.08; e.burst=3;
      // muzzle pos
    }
    if(e.burst>0){ e.burstT=(e.burstT||0)-dt; if(e.burstT<=0){ e.burstT=0.14; e.burst--; eshot();
      const from=e.g.position.clone().add(new THREE.Vector3(0,1.4,0)); const dir=new THREE.Vector3(player.pos.x-from.x,(player.pos.y-0.2)-from.y,player.pos.z-from.z).normalize();
      dir.x+=(Math.random()-0.5)*(0.09+dist*0.002); dir.y+=(Math.random()-0.5)*0.05; dir.z+=(Math.random()-0.5)*(0.09+dist*0.002); dir.normalize();
      spawnTracer(from,dir,true);
      // hit chance: ray to player + cover check
      ray.set(from,dir); ray.far=dist+3; const blocks=ray.intersectObjects(scene.children.filter(o=>o.geometry&&o.geometry.type==='BoxGeometry'),false)[0];
      const aimErr=Math.hypot(dir.x,dir.z);
      if(Math.random()<0.42&&dist<30)damagePlayer(e.dmg*(dist<12?1.2:0.9),e.g.position);
      else if(Math.random()<0.2)damagePlayer(e.dmg*0.6,e.g.position);
    } }
  }
  if(waveActive&&alive===0&&!gameOver){ waveActive=false; // cleanup corpses
    for(let i=enemies.length-1;i>=0;i--)scene.remove(enemies[i].g); enemies.length=0;
    player.hp=Math.min(player.maxHp,player.hp+25); gun.reserve=Math.min(180,gun.reserve+30); updateHP(); updateAmmo();
    if(wave>=WAVES.length){ win(); } else { feed(`✔ Wave ${wave} cleared · +25 HP +30 AMMO`); snd(660,0.15,'sine',0.15,990); setTimeout(()=>{ if(!gameOver)nextWave(); },2200); } }
  updatePills(); drawMinimap();
}
function perfNow(){ return performance.now(); }

/* ================= MINIMAP ================= */
const mm=document.getElementById('minimap').getContext('2d');
function drawMinimap(){ const S=150,C=75,sc=S/(ARENA*2+16); mm.clearRect(0,0,S,S);
  mm.fillStyle='rgba(20,34,24,.9)'; mm.fillRect(0,0,S,S);
  mm.strokeStyle='rgba(255,255,255,.2)'; mm.strokeRect(4,4,S-8,S-8);
  // crates
  mm.fillStyle='rgba(200,180,120,.5)'; for(const c of colliders){ mm.fillRect(C+c.x*sc-2,C+c.z*sc-2,4,4); }
  const dot=(x,z,col,r=3)=>{ mm.fillStyle=col; mm.beginPath(); mm.arc(C+x*sc,C+z*sc,r,0,7); mm.fill(); };
  for(const e of enemies){ if(!e.dead)dot(e.g.position.x,e.g.position.z,'#ff4444',3.4); }
  for(const p of pickups)dot(p.m.position.x,p.m.position.z,p.kind==='hp'?'#39e75f':'#ffcc00',2.4);
  // player arrow
  mm.save(); mm.translate(C+player.pos.x*sc,C+player.pos.z*sc); mm.rotate(Math.atan2(Math.sin(player.yaw),Math.cos(player.yaw))+Math.PI);
  mm.fillStyle='#fff'; mm.beginPath(); mm.moveTo(0,-7); mm.lineTo(5,5); mm.lineTo(0,2); mm.lineTo(-5,5); mm.closePath(); mm.fill(); mm.restore();
}

/* ================= FLOATERS / FX ================= */
const proj=new THREE.Vector3();
function updateFloaters(){ for(let i=floaters.length-1;i>=0;i--){ const f=floaters[i]; f.life-=1/60; f.p.y+=1/60*1.2;
    proj.copy(f.p).project(camera); if(proj.z>1){f.el.style.display='none';} else { f.el.style.display='block';
    f.el.style.left=((proj.x*0.5+0.5)*innerWidth)+'px'; f.el.style.top=((-proj.y*0.5+0.5)*innerHeight)+'px'; f.el.style.opacity=Math.min(1,f.life*2); }
    if(f.life<=0){f.el.remove();floaters.splice(i,1);} } }
function updateFx(dt){ for(let i=tracers.length-1;i>=0;i--){ tracers[i].life-=dt; tracers[i].m.material.opacity=tracers[i].life/0.07; if(tracers[i].life<=0){scene.remove(tracers[i].m);tracers.splice(i,1);} }
  for(let i=impacts.length-1;i>=0;i--){ const im=impacts[i]; im.life-=dt; im.v.y-=12*dt; im.m.position.addScaledVector(im.v,dt); im.m.material.transparent=true; im.m.material.opacity=Math.max(0,im.life*2); if(im.life<=0){scene.remove(im.m);impacts.splice(i,1);} }
  for(const c of clouds){ c.position.x+=dt*0.7; if(c.position.x>120)c.position.x=-120; }
  for(const f of flags){ f.rotation.y=Math.sin(performance.now()*0.003)*0.3; } }

/* ================= LOOP ================= */
let last=performance.now();
function loop(){ requestAnimationFrame(loop); const now=performance.now(); let dt=(now-last)/1000; last=now; dt=Math.min(dt,0.05);
