input.content:
const { chromium } = require('playwright-core');
(async () => {
  const url = process.argv[2] || 'file:///Users/runner/work/PlayGround/PlayGround/index.html';
  const browser = await chromium.launch({ args: ['--use-gl=swiftshader','--enable-unsafe-swiftshader','--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text().slice(0,220)); });
  page.on('pageerror', e => errors.push('PAGEERROR: '+String(e).slice(0,220)));
  await page.goto(url, { waitUntil: 'networkidle', timeout: 60000 });
  await page.waitForTimeout(6000);
  await page.screenshot({ path: 'screenshots/menu.png' });
  const pre = await page.evaluate(() => window.__game ? window.__game.assets : null);
  console.log('PRE_ASSETS:', JSON.stringify(pre));
  await page.click('#playBtn').catch(e => console.log('click fail', e.message));
  await page.waitForTimeout(5000);
  await page.screenshot({ path: 'screenshots/gameplay.png' });
  const mid = await page.evaluate(() => ({ assets: window.__game.assets, wave: window.__game.wave, alive: window.__game.enemies.filter(e=>!e.dead).length }));
  console.log('MID:', JSON.stringify(mid));
  for (let i = 0; i < 60; i++) {
    await page.evaluate(() => window.__game.debugKillNearest());
    await page.waitForTimeout(120);
    const k = await page.evaluate(() => window.__game.player.kills);
    if (k > 0) break;
  }
  const st = await page.evaluate(() => ({ kills: window.__game.player.kills, shots: window.__game.player.shots, hits: window.__game.player.hits, mag: window.__game.gun.mag, hp: Math.round(window.__game.player.hp) }));
  console.log('COMBAT:', JSON.stringify(st));
  await page.screenshot({ path: 'screenshots/combat.png' });
  console.log('ERRORS:', JSON.stringify(errors.filter(e=>!e.includes('pointer lock')).slice(0,8)));
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

