const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({ args: ['--use-gl=swiftshader','--enable-unsafe-swiftshader','--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text().slice(0,220)); });
  page.on('pageerror', e => errors.push('PAGEERROR: '+String(e).slice(0,220)));
  await page.goto('file:///var/folders/d8/hvxvltxn0fl4rmnd52sncbth0000gn/T/opencode/inline-test.html', { waitUntil: 'networkidle', timeout: 60000 });
  await page.waitForTimeout(5000);
  await page.click('#playBtn').catch(()=>{});
  await page.waitForTimeout(4000);
  // aim at nearest enemy and hold fire for a mid-burst screenshot (muzzle flash / tracer check)
  await page.evaluate(() => window.__game.debugKillNearest());
  await page.evaluate(() => window.__game.setFiring(true));
  await page.waitForTimeout(320);
  await page.screenshot({ path: 'screenshots/firing.png' });
  await page.evaluate(() => window.__game.setFiring(false));
  const st = await page.evaluate(() => ({ mag: window.__game.gun.mag, shots: window.__game.player.shots }));
  console.log('FIRING:', JSON.stringify(st));
  console.log('ERRORS:', JSON.stringify(errors.filter(e=>!e.includes('pointer lock')).slice(0,8)));
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

