const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({ args: ['--use-gl=swiftshader','--enable-unsafe-swiftshader','--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: '+String(e).slice(0,200)));
  await page.goto('file:///var/folders/d8/hvxvltxn0fl4rmnd52sncbth0000gn/T/opencode/inline-test.html', { waitUntil: 'networkidle', timeout: 60000 });
  await page.waitForTimeout(5000);
  await page.click('#playBtn').catch(()=>{});
  await page.waitForTimeout(2500);
  let won = false;
  for (let i = 0; i < 500; i++) {
    await page.evaluate(() => { window.__game.debugKillNearest(); });
    await page.waitForTimeout(100);
    won = await page.evaluate(() => !document.getElementById('end').classList.contains('hidden'));
    if (won) break;
  }
  const wst = await page.evaluate(() => ({ kills: window.__game.player.kills, wave: window.__game.wave, title: document.getElementById('endTitle').textContent }));
  console.log('WIN:', JSON.stringify(wst));
  await page.waitForTimeout(600);
  await page.screenshot({ path: 'screenshots/win.png' });
  // lose path: restart, then lethal damage
  await page.click('#againBtn').catch(()=>{});
  await page.waitForTimeout(2500);
  await page.evaluate(() => window.__game.hurt(500));
  await page.waitForTimeout(800);
  const lst = await page.evaluate(() => ({ title: document.getElementById('endTitle').textContent, sub: document.getElementById('endSub').textContent }));
  console.log('LOSE:', JSON.stringify(lst));
  await page.screenshot({ path: 'screenshots/lose.png' });
  console.log('ERRORS:', JSON.stringify(errors.filter(e=>!e.includes('pointer lock')).slice(0,8)));
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

