 /* ================= ENEMY AI ================= */
 const tmpV=new THREE.Vector3();
 function updateEnemies(dt,now){ let alive=0;
   for(const e of enemies){ if(e.dead){ e.deathT+=dt; e.g.rotation.x=Math.min(Math.PI/2,e.deathT*4); e.g.position.y=Math.max(-0.4,e.g.position.y-dt*0.4); e.bar.visible=false;
       if(e.deathT>3){scene.remove(e.g);} continue; }
     alive++; if(e.mixer)e.mixer.update(dt); // GLB walk cycle
     if(e.flashT>0){ e.flashT-=dt; if(e.flashT<=0&&e.mats)for(const m of e.mats){ if(m.emissive){ m.emissive.setHex(0x000000); m.emissiveIntensity=0; } } }
     alive++; tmpV.set(player.pos.x-e.g.position.x,0,player.pos.z-e.g.position.z); const dist=tmpV.length(); tmpV.normalize();
     e.strafe+=dt*0.8*e.strafeDir; if(Math.random()<dt*0.3)e.strafeDir*=-1;
     // movement: approach until ~10m, then strafe
     let mx=0,mz=0;
     if(dist>11){ mx=tmpV.x*e.speed; mz=tmpV.z*e.speed; }
     else if(dist<6){ mx=-tmpV.x*e.speed*0.8; mz=-tmpV.z*e.speed*0.8; }
     else { mx=-tmpV.z*e.strafeDir*e.speed*0.6+tmpV.x*0.3; mz=tmpV.x*e.strafeDir*e.speed*0.6+tmpV.z*0.3; }
     e.g.position.x+=mx*dt; e.g.position.z+=mz*dt;
     // collide with cover (cheap)
     const p=e.g.position; for(const c of colliders){ const dx=p.x-c.x,dz=p.z-c.z; const px=c.hx+0.5-Math.abs(dx),pz=c.hz+0.5-Math.abs(dz);
       if(px>0&&pz>0){ if(px<pz)p.x=c.x+Math.sign(dx||1)*(c.hx+0.5); else p.z=c.z+Math.sign(dz||1)*(c.hz+0.5); } }
     p.x=Math.max(-ARENA,Math.min(ARENA,p.x)); p.z=Math.max(-ARENA,Math.min(ARENA,p.z));
     e.g.rotation.y=Math.atan2(tmpV.x,-tmpV.z)+Math.PI; // face player (model faces -z? adjust)
     e.g.rotation.y=Math.atan2(player.pos.x-p.x,player.pos.z-p.z);
