       const from=e.g.position.clone().add(new THREE.Vector3(0,1.4,0)); const dir=new THREE.Vector3(player.pos.x-from.x,(player.pos.y-0.2)-from.y,player.pos.z-from.z).normalize();
       dir.x+=(Math.random()-0.5)*(0.09+dist*0.002); dir.y+=(Math.random()-0.5)*0.05; dir.z+=(Math.random()-0.5)*(0.09+dist*0.002); dir.normalize();
       spawnTracer(from,dir,true);
       // hit chance: ray to player + cover check
       ray.set(from,dir); ray.far=dist+3; const blocks=ray.intersectObjects(scene.children.filter(o=>o.geometry&&o.geometry.type==='BoxGeometry'),false)[0];
       const aimErr=Math.hypot(dir.x,dir.z);
       if(Math.random()<0.42&&dist<30)damagePlayer(e.dmg*(dist<12?1.2:0.9),e.g.position);
       else if(Math.random()<0.2)damagePlayer(e.dmg*0.6,e.g.position);
     } }
   }
   if(waveActive&&alive===0&&!gameOver){ waveActive=false; // cleanup corpses
     for(let i=enemies.length-1;i>=0;i--)scene.remove(enemies[i].g); enemies.length=0;
     player.hp=Math.min(player.maxHp,player.hp+25); gun.reserve=Math.min(180,gun.reserve+30); updateHP(); updateAmmo();
     if(wave>=WAVES.length){ win(); } else { feed(`✔ Wave ${wave} cleared · +25 HP +30 AMMO`); snd(660,0.15,'sine',0.15,990); setTimeout(()=>{ if(!gameOver)nextWave(); },2200); } }
   updatePills(); drawMinimap();
 }
