 const proj=new THREE.Vector3();
 function updateFloaters(){ for(let i=floaters.length-1;i>=0;i--){ const f=floaters[i]; f.life-=1/60; f.p.y+=1/60*1.2;
     proj.copy(f.p).project(camera); if(proj.z>1){f.el.style.display='none';} else { f.el.style.display='block';
     f.el.style.left=((proj.x*0.5+0.5)*innerWidth)+'px'; f.el.style.top=((-proj.y*0.5+0.5)*innerHeight)+'px'; f.el.style.opacity=Math.min(1,f.life*2); }
     if(f.life<=0){f.el.remove();floaters.splice(i,1);} } }
